$ErrorActionPreference='Stop'
Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Runtime.InteropServices;
public static class Oracle {
 [StructLayout(LayoutKind.Sequential)] public struct Input {public IntPtr Data;public UIntPtr Size;public int Editable;}
 [StructLayout(LayoutKind.Sequential)] public struct Output {public IntPtr Data;public UIntPtr Size;}
 [StructLayout(LayoutKind.Sequential)] public struct Hash {public uint Size;[MarshalAs(UnmanagedType.ByValArray,SizeConst=32)]public byte[] Value;}
 [StructLayout(LayoutKind.Sequential)] public struct Header {public long TypeSet,Type,Flags;public UIntPtr TargetSize;public long FileTime;public uint Alg;public Hash Hash;}
 [DllImport("msdelta.dll",SetLastError=true)]static extern bool CreateDeltaB(long type,long set,long reset,Input source,Input target,Input so,Input to,Input go,ref long time,uint alg,out Output result);
 [DllImport("msdelta.dll",SetLastError=true)]static extern bool ApplyDeltaB(long flags,Input source,Input delta,out Output result);
 [DllImport("msdelta.dll",SetLastError=true)]static extern bool GetDeltaInfoB(Input delta,out Header header);
 [DllImport("msdelta.dll")]static extern bool DeltaFree(IntPtr ptr);
 static Input Pin(byte[] a,out GCHandle pin){if(a.Length==0){pin=default(GCHandle);return new Input();}pin=GCHandle.Alloc(a,GCHandleType.Pinned);return new Input{Data=pin.AddrOfPinnedObject(),Size=(UIntPtr)a.Length};}
 static void Free(GCHandle h){if(h.IsAllocated)h.Free();}
 static byte[] Take(Output o){try{byte[] b=new byte[(int)o.Size.ToUInt64()];Marshal.Copy(o.Data,b,0,b.Length);return b;}finally{DeltaFree(o.Data);}}
 public static byte[] RandomData(int size){byte[] b=new byte[size];uint x=5071;for(int i=0;i<size;i++){x^=x<<13;x^=x>>17;x^=x<<5;b[i]=(byte)x;}return b;}
 public static byte[] Create(byte[] s,byte[] t,uint alg){GCHandle sp,tp;Input si=Pin(s,out sp),ti=Pin(t,out tp);try{Output o;long time=132537600000000000;if(!CreateDeltaB(1,0,0,si,ti,new Input(),new Input(),new Input(),ref time,alg,out o))throw new Exception("CreateDeltaB:"+Marshal.GetLastWin32Error());return Take(o);}finally{Free(sp);Free(tp);}}
 public static byte[] Apply(byte[] s,byte[] d){GCHandle sp,dp;Input si=Pin(s,out sp),di=Pin(d,out dp);try{Output o;if(!ApplyDeltaB(0,si,di,out o))throw new Exception("ApplyDeltaB:"+Marshal.GetLastWin32Error());return Take(o);}finally{Free(sp);Free(dp);}}
 public static Header Info(byte[] d){GCHandle dp;Input di=Pin(d,out dp);try{Header h;if(!GetDeltaInfoB(di,out h))throw new Exception("GetDeltaInfoB:"+Marshal.GetLastWin32Error());return h;}finally{Free(dp);}}
}
'@
$root='C:\pa30-oracle';New-Item -ItemType Directory -Force $root|Out-Null
$cases=@(
 @{Name='empty-literal';Source=[byte[]]@();Target=[Text.Encoding]::ASCII.GetBytes('abc');Alg=32771},
 @{Name='empty-repeated';Source=[byte[]]@();Target=[Text.Encoding]::ASCII.GetBytes(('hello world! '*300));Alg=32771},
 @{Name='source-copy';Source=[Text.Encoding]::ASCII.GetBytes(('The quick brown fox jumps over the lazy dog. '*80));Target=[Text.Encoding]::ASCII.GetBytes(('The quick brown fox jumps over the lazy dog. '*40)+'CHANGED'+('The quick brown fox jumps over the lazy dog. '*40));Alg=32771},
 @{Name='random-mutated';Source=[Convert]::FromBase64String('');Target=[Convert]::FromBase64String('');Alg=32771},
 @{Name='empty-random';Source=[Convert]::FromBase64String('');Target=[Convert]::FromBase64String('');Alg=32771},
 @{Name='source-offset';Source=[Convert]::FromBase64String('');Target=[Convert]::FromBase64String('');Alg=32771},
 @{Name='source-reordered';Source=[Convert]::FromBase64String('');Target=[Convert]::FromBase64String('');Alg=32771},
 @{Name='long-repeated';Source=[Convert]::FromBase64String('');Target=[Convert]::FromBase64String('');Alg=32771},
 @{Name='extended-offset';Source=[Oracle]::RandomData(600000);Target=([byte[]]([Oracle]::RandomData(600000))[0..4095]);Alg=32771},
 @{Name='extended-offset-2m';Source=[Oracle]::RandomData(2000000);Target=([byte[]]([Oracle]::RandomData(2000000))[0..4095]);Alg=32771},
 @{Name='extended-offset-20m';Source=[Oracle]::RandomData(20000000);Target=([byte[]]([Oracle]::RandomData(20000000))[0..4095]);Alg=32771},
 @{Name='sha1-literal';Source=[byte[]]@();Target=[Text.Encoding]::ASCII.GetBytes('native SHA1 fixture');Alg=32772},
 @{Name='md5-literal';Source=[byte[]]@();Target=[Text.Encoding]::ASCII.GetBytes('native PA30 fixture');Alg=32771}
)
$rows=@();foreach($c in $cases){$d=[Oracle]::Create($c.Source,$c.Target,$c.Alg);$a=[Oracle]::Apply($c.Source,$d);if([Convert]::ToBase64String($a)-ne[Convert]::ToBase64String($c.Target)){throw 'oracle mismatch'}
 foreach($item in @(@('source',$c.Source),@('target',$c.Target),@('delta',$d))){[IO.File]::WriteAllBytes("$root\$($c.Name).$($item[0])",$item[1])}
 $h=[Oracle]::Info($d);$rows+=@{name=$c.Name;source_size=$c.Source.Length;target_size=$c.Target.Length;delta_size=$d.Length;file_type_set=$h.TypeSet;file_type=$h.Type;flags=$h.Flags;hash_alg=$h.Alg;target_hash=[BitConverter]::ToString($h.Hash.Value[0..($h.Hash.Size-1)]).Replace('-','').ToLowerInvariant();native_roundtrip=$true}
}
$rows|ConvertTo-Json -Depth 5|Set-Content -Encoding UTF8 "$root\manifest.json"
$rows|ConvertTo-Json -Depth 5
